mapper.select:
SELECT t.status AS status, COUNT(*) AS count
FROM sale_lead t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

GROUP BY t.status

SELECT COUNT(*)
FROM sale_lead t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COUNT(DISTINCT lg.lead_id)
FROM crm_lead_log lg
INNER JOIN sale_lead t ON t.id = lg.lead_id AND t.deleted = 0
WHERE lg.log_type = 4
  AND lg.create_time >= #{start}
  AND lg.create_time <= #{end}

SELECT
    COALESCE(t.source, 'UNKNOWN') AS source,
    COALESCE(t.source, 'UNKNOWN') AS sourceLabel,
    COUNT(*) AS leadCount,
    SUM(CASE WHEN t.status = 3 THEN 1 ELSE 0 END) AS convertedCount,
    CASE WHEN COUNT(*) = 0 THEN 0
         ELSE ROUND(SUM(CASE WHEN t.status = 3 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2)
    END AS conversionRate,
    COALESCE((
        SELECT SUM(o.total_amount)
        FROM customer_info ci
        INNER JOIN orders o
            ON o.customer_id = ci.id
            AND o.status = 'PAID'
            AND (o.order_type IS NULL OR o.order_type = 'NORMAL')
            AND o.pay_time IS NOT NULL
            AND o.pay_time >= #{start}
            AND o.pay_time <= #{end}
        WHERE ci.lead_id IN (
              SELECT tx.id FROM sale_lead tx
              WHERE tx.deleted = 0
                AND COALESCE(tx.source, 'UNKNOWN') = COALESCE(t.source, 'UNKNOWN')
                AND tx.create_time >= #{start}
                AND tx.create_time <= #{end}

                    AND tx.tenant_id = #{ctx.tenantId}


                    AND (
                        tx.owner_user IN
                        #{u}
                        OR (tx.owner_user IS NULL AND tx.create_by IN
                            #{u}
                        )
                    )


                    AND (
                        tx.owner_user IN
                        #{u}
                        OR tx.create_by IN
                        #{u}
                    )

          )
    ), 0) AS orderAmount
FROM sale_lead t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

GROUP BY t.source
ORDER BY leadCount DESC

SELECT COALESCE(ROUND(AVG(cnt), 2), 0) FROM (
    SELECT (
        SELECT COUNT(*)
        FROM crm_lead_log lg
        WHERE lg.lead_id = t.id AND lg.log_type = 2
    ) AS cnt
    FROM sale_lead t
    WHERE t.deleted = 0
      AND t.create_time >= #{start}
      AND t.create_time <= #{end}

) AS c
